import{state,setState}from"./state.js";import{addChild,savePreference}from"./api.js";import{renderAll}from"./ui.js";import{showToast,closeModal,openModal}from"./utils.js";import{refreshChildLinkInline}from"./admin-settings.js";import{useChildTheme}from"./age-theme.js";function getNumericLimit(e,t){const i=Number(e);return Number.isFinite(i)?i:t}function getMonthlyLimit(e){return getNumericLimit(e?.monthlyLimit??e?.monthly_limit,1e4)}function getDailyLimit(e){return getNumericLimit(e?.dailyCoinLimit??e?.daily_coin_limit,0)}function updateSettingsFields(e){const t={"settings-child-name-inline":e.name,"settings-child-monthly-limit-inline":getMonthlyLimit(e),"settings-child-day-coin-limit-inline":getDailyLimit(e)};Object.keys(t).forEach(e=>{const i=document.getElementById(e);i&&(i.value=t[e])})}export function switchChild(e){if(!e)return;const t=state.children.find(t=>t.id==e);setState({currentChildId:e,balance:t?.balance||0,monthlyLimit:getMonthlyLimit(t),dailyCoinLimit:getDailyLimit(t)}),localStorage.setItem("earnit-last-child-id",e),savePreference("lastSelectedChildId",e),renderAll();const i=document.getElementById("analytics-section");i&&!i.classList.contains("hidden")&&import("./analytics-ui.js").then(e=>e.loadAnalytics()),t&&(updateSettingsFields(t),refreshChildLinkInline()),useChildTheme(e,t?.theme)}export function openAddChildModal(){document.getElementById("new-child-name").value="",openModal("add-child-modal")}export async function saveNewChild(){const e=document.getElementById("new-child-name").value.trim();if(!e)return showToast("Введите имя","error");const t=await addChild(e);t.success?(showToast("Ребенок добавлен!","success"),closeModal("add-child-modal"),window.location.reload()):showToast("Ошибка: "+(t.error||"Не удалось добавить"),"error")}